result:
    /deep/.ivu-input{
		font-size: 12px!important
	}
	/deep/.ivu-input-wrapper{
		width: 240px;
	}
	/deep/.ivu-input-word-count{
		color: #BBBBBB;
	}
	/deep/.ivu-input-icon{
		color: #BBBBBB;
	}
    .c_product{
		padding: 0 15px 20px 15px
		.list-box{
			.item{
				display: flex;
				align-items: center;
				position relative
				margin-top 23px
				padding 18px 20px 18px 0;
				background-color: #F9F9F9
				border-radius: 3px;

				.delete{
					position absolute
					right 0
					top 0
					right: -13px;
					top: -14px;
					color #ccc;
					cursor pointer
				}
			}

			.move-icon{
				display flex
				align-items center
				justify-content center
				width 50px
				cursor move
			}

			.con-item{
				display flex
				align-items center
				margin-bottom 15px

				&:last-child{
					margin-bottom 0
				}
				span{
					width 75px
					font-size 12px
					color: #999999;
				}
			}
		}

		.add-btn{
			margin-top 21px
			.btn{
				width: 100%; 
				height: 36px; 
				border-color:#EEEEEE; 
				color: #666666;
				.iconfont{
					font-size: 11px;
					margin-right: 5px;
				}
			}
		}
	}
    .title{
		font-size: 12px
		color: #999
	}
    .iconfont-diy{
		color: #DDDDDD
		font-size: 16px
	}
